# =============================================================================
# HELPERS
# =============================================================================

def safe_float(
    value: Any,
) -> float | None:

    try:

        number = float(value)

        if number != number:
            return None

        return number

    except (
        TypeError,
        ValueError,
    ):

        return None


def safe_int(
    value: Any,
) -> int | None:

    try:

        number = float(value)

        if number != number:
            return None

        return int(number)

    except (
        TypeError,
        ValueError,
    ):

        return None


def format_pct(
    value: Any,
    decimals: int = 2,
) -> str:

    number = safe_float(value)

    if number is None:

        return "N/A"

    return f"{number * 100:.{decimals}f}%"


def format_money(
    value: Any,
) -> str:

    number = safe_float(value)

    if number is None:

        return "N/A"

    return f"₹{number:,.0f}"


def format_nav(
    value: Any,
) -> str:

    number = safe_float(value)

    if number is None:

        return "N/A"

    return f"₹{number:,.4f}"


def format_number(
    value: Any,
    decimals: int = 3,
) -> str:

    number = safe_float(value)

    if number is None:

        return "N/A"

    return f"{number:.{decimals}f}"


def format_datetime(
    value: Any,
) -> str:

    if value is None:

        return "N/A"

    text = str(value).strip()

    if not text:

        return "N/A"

    try:

        dt = datetime.fromisoformat(
            text.replace(
                "Z",
                "+00:00",
            )
        )

        return dt.strftime(
            "%Y-%m-%d %H:%M:%S"
        )

    except ValueError:

        return text


def get_file_modified_time(
    filename: Path,
) -> datetime | None:

    try:

        return datetime.fromtimestamp(
            filename.stat().st_mtime
        )

    except OSError:

        return None


def days_since(
    dt: datetime | None,
) -> float | None:

    if dt is None:

        return None

    return (
        datetime.now()
        - dt
    ).total_seconds() / 86400.0


