# =============================================================================
# LOAD SUMMARY
# =============================================================================

def load_summary() -> dict:

    try:

        with SUMMARY_FILE.open(
            "r",
            encoding="utf-8",
        ) as file:

            payload = json.load(file)

    except Exception as exc:

        raise RuntimeError(
            "Unable to read summary.json:\n"
            f"{exc}"
        ) from exc

    if not isinstance(
        payload,
        dict,
    ):

        raise RuntimeError(
            "summary.json does not contain "
            "a JSON object."
        )

    return payload


# =============================================================================
# LAST BACKTEST INFORMATION
# =============================================================================

def get_last_backtest_datetime(
    summary: dict,
) -> tuple[
    datetime | None,
    str,
]:

    # Try common timestamp fields first.

    possible_fields = [
        "run_timestamp",
        "generated_at",
        "created_at",
        "timestamp",
        "run_datetime",
        "backtest_run_time",
        "last_run",
    ]

    for field in possible_fields:

        value = summary.get(
            field
        )

        if not value:

            continue

        text = str(value).strip()

        try:

            parsed = datetime.fromisoformat(
                text.replace(
                    "Z",
                    "+00:00",
                )
            )

            if parsed.tzinfo is not None:

                parsed = parsed.replace(
                    tzinfo=None
                )

            return (
                parsed,
                f"summary.json -> {field}",
            )

        except ValueError:

            continue

    # Fallback:
    #
    # If backtest.py did not save a run timestamp,
    # use summary.json modification time.
    #
    # This does NOT run anything.

    modified = get_file_modified_time(
        SUMMARY_FILE
    )

    return (
        modified,
        "summary.json file modification time",
    )


# =============================================================================
# RESEARCH FRESHNESS
# =============================================================================

def check_research_freshness(
    summary: dict,
) -> tuple[
    datetime | None,
    bool,
]:

    last_run, source = (
        get_last_backtest_datetime(
            summary
        )
    )

    print("=" * 100)
    print("RESEARCH FRESHNESS")
    print("=" * 100)

    print()

    print(
        f"Last backtest run       : "
        f"{format_datetime(last_run)}"
    )

    print(
        f"Timestamp source        : "
        f"{source}"
    )

    age = days_since(
        last_run
    )

    if age is None:

        print(
            "Research age            : "
            "UNKNOWN"
        )

        print()

        print(
            "WARNING: Unable to determine "
            "research age."
        )

        print(
            "main.py will not run a backtest."
        )

        print()

        return (
            last_run,
            False,
        )

    print(
        f"Research age            : "
        f"{age:.1f} days"
    )

    print(
        f"Maximum allowed age     : "
        f"{MAX_RESULT_AGE_DAYS} days"
    )

    print()

    if age > MAX_RESULT_AGE_DAYS:

        print(
            "STATUS                  : "
            "STALE RESULTS"
        )

        print()

        print(
            "No new backtest will be run automatically."
        )

        print(
            "Run backtest.py manually to refresh research."
        )

        print()

        return (
            last_run,
            False,
        )

    print(
        "STATUS                  : "
        "FRESH ENOUGH FOR PRODUCTION READ"
    )

    print()

    return (
        last_run,
        True,
    )


