# =============================================================================
# STRATEGY SELECTION
# =============================================================================

def select_live_strategy(
    summary: dict,
) -> tuple[
    str | None,
    str | None,
    str | None,
]:

    highest_xirr = summary.get(
        "strongest_return_strategy"
    )

    highest_risk_adjusted = summary.get(
        "strongest_risk_adjusted_strategy"
    )

    if (
        highest_xirr
        and highest_risk_adjusted
        and
        str(highest_xirr).upper()
        ==
        str(highest_risk_adjusted).upper()
    ):

        strategy = str(
            highest_xirr
        ).upper()

        return (
            strategy,
            strategy,
            strategy,
        )

    return (
        None,
        (
            str(highest_xirr).upper()
            if highest_xirr
            else None
        ),
        (
            str(highest_risk_adjusted).upper()
            if highest_risk_adjusted
            else None
        ),
    )


