# =============================================================================
# CURRENT TOP 5
# =============================================================================

def load_current_top5(
    strategy: str,
):

    filename = (
        RESULTS_DIR
        /
        f"current_top5_{strategy.lower()}.csv"
    )

    if not filename.exists():

        return None, filename

    try:

        import pandas as pd

        df = pd.read_csv(
            filename
        )

    except Exception as exc:

        raise RuntimeError(
            f"Unable to read {filename.name}:\n"
            f"{exc}"
        ) from exc

    if df.empty:

        return None, filename

    if "rank" in df.columns:

        df = df.sort_values(
            "rank"
        )

    return (
        df.reset_index(
            drop=True
        ),
        filename,
    )


