    files = sorted(
        file
        for file in RESULTS_DIR.iterdir()
        if file.is_file()
    )

    if not files:

        print(
            "No files found."
        )

        print()

        return

    for file in files:

        try:

            size_kb = (
                file.stat().st_size
                / 1024
            )

            modified = get_file_modified_time(
                file
            )

            print(
                f"{file.name:<60}"
                f"{size_kb:>10.1f} KB"
                f"  {format_datetime(modified)}"
            )

        except OSError:

            print(
                file.name
            )

    print()


