# =============================================================================
# MAIN
# =============================================================================

def main() -> int:

    start_time = time.perf_counter()

    live_strategy: str | None = None

    research_fresh = False

    sip_action_available = False

    try:

        # =====================================================================
        # HEADER
        # =====================================================================

        print_header()

        # =====================================================================
        # VALIDATE EXISTING RESULTS
        # =====================================================================

        validate_result_files()

        # =====================================================================
        # LOAD SAVED SUMMARY
        # =====================================================================

        summary = load_summary()

        # =====================================================================
        # CHECK RESEARCH FRESHNESS
        # =====================================================================

        (
            last_backtest_run,
            research_fresh,
        ) = check_research_freshness(
            summary
        )

        # =====================================================================
        # SAVED RESEARCH CONFIGURATION
        # =====================================================================

        print_saved_research_configuration(
            summary
        )

        # =====================================================================
        # SELECT STRATEGY FROM SAVED RESULTS
        # =====================================================================

        (
            live_strategy,
            highest_xirr_strategy,
            highest_risk_strategy,
        ) = select_live_strategy(
            summary
        )

        print_strategy_selection(
            live_strategy,
            summary,
        )

        # =====================================================================
        # STRATEGY METHODOLOGY
        # =====================================================================

        print_strategy_methodology(
            live_strategy
        )

        # =====================================================================
        # HISTORICAL EVIDENCE
        # =====================================================================

        print_historical_evidence(
            live_strategy
        )

        # =====================================================================
        # CURRENT MARKET
        # =====================================================================

        print_current_market(
            summary
        )

        # =====================================================================
        # CURRENT TOP 5
        # =====================================================================

        current_top5 = None

        current_top5_file = None

        if live_strategy is not None:

            (
                current_top5,
                current_top5_file,
            ) = load_current_top5(
                live_strategy
            )

            if current_top5 is None:

                print()

                print(
                    "=" * 100
                )

                print(
                    "CURRENT TOP 5"
                )

                print(
                    "=" * 100
                )

                print()

                print(
                    "Current Top 5 file not found:"
                )

                print(
                    f"  {current_top5_file}"
                )

                print()

            else:

                print_current_top5(
                    current_top5,
                    live_strategy,
                )

        # =====================================================================
        # SIP ACTION
        # =====================================================================

        if (
            live_strategy is not None
            and
            research_fresh
            and
            current_top5 is not None
            and
            not current_top5.empty
        ):

            print_current_top1_action(
                current_top5,
                live_strategy,
                summary,
            )

            sip_action_available = True

        else:

            print()

            print(
                "=" * 100
            )

            print(
                "CURRENT MONTHLY SIP ACTION"
            )

            print(
                "=" * 100
            )

            print()

            print(
                "NO SIP ACTION ISSUED."
            )

            print()

            if not research_fresh:

                print(
                    "Reason: saved research is stale or "
                    "its age could not be verified."
                )

                print(
                    "Run backtest.py manually to refresh it."
                )

            elif live_strategy is None:

                print(
                    "Reason: highest-XIRR and highest-risk-adjusted "
                    "strategies disagree."
                )

            elif current_top5 is None:

                print(
                    "Reason: current Top 5 result file is missing."
                )

            print()

            print(
                "main.py will NOT run backtest.py automatically."
            )

            print()

        # =====================================================================
        # DRAWdown
        # =====================================================================

        print_drawdown_explanation()

        # =====================================================================
        # SIP MECHANICS
        # =====================================================================

        print_sip_mechanics()

        # =====================================================================
        # BACKTEST OBSERVATIONS
        # =====================================================================

        print_backtest_observations(
            summary
        )

        # =====================================================================
        # METHODOLOGY
        # =====================================================================

        print_methodology(
            summary
        )

        # =====================================================================
        # LIMITATIONS
        # =====================================================================

        print_limitations()

        # =====================================================================
        # RESULT FILES
        # =====================================================================

        print_result_files()

        # =====================================================================
        # FINAL STATUS
        # =====================================================================

        elapsed = (
            time.perf_counter()
            - start_time
        )

        print_final_status(
            live_strategy,
            RESULTS_DIR,
            elapsed,
            research_fresh,
            sip_action_available,
        )

        return 0

    except KeyboardInterrupt:

        elapsed = (
            time.perf_counter()
            - start_time
        )

        print()

        print("=" * 100)
        print("SMALLCAPSIPLAB - INTERRUPTED")
        print("=" * 100)

        print()

        print(
            f"Runtime before interruption : "
            f"{elapsed:.2f} seconds"
        )

        print()

        return 130

    except Exception as exc:

        elapsed = (
            time.perf_counter()
            - start_time
        )

        print()

        print("=" * 100)
        print("SMALLCAPSIPLAB - FAILED")
        print("=" * 100)

        print()

        print(
            f"Error                      : "
            f"{exc}"
        )

        print()

        print(
            f"Runtime before failure     : "
            f"{elapsed:.2f} seconds"
        )

        print()

        raise


# =============================================================================
# SCRIPT ENTRY
# =============================================================================

if __name__ == "__main__":

    raise SystemExit(
        main()
    )